}

/// Data needed to emit a checksum line for one input.
pub struct ChecksumRecord {
    pub columns: crate::sum::DigestColumns,
    pub stdin_input: bool,
    pub filename: PathBuf,
}

impl ChecksumRecord {
    pub fn new(
        file_bytes: usize,
        digest_text: String,
        asterisk: bool,
        stdin_input: bool,
        filename: PathBuf,
    ) -> Self {
        Self {
            columns: crate::sum::DigestColumns::new(file_bytes, digest_text, asterisk),
            stdin_input,
            filename,
        }
    }
}

#[derive(Default)]
